-- Run AFTER schema.sql. Optional extended features used by the current frontend.
begin;
create table public.custom_lessons(id uuid primary key default gen_random_uuid(),owner uuid not null default auth.uid() references public.profiles on delete cascade,class_id uuid references public.classes on delete cascade,title text not null check(length(title) between 1 and 150),body text not null check(length(body) between 1 and 40000),video_url text check(length(video_url)<=1000),scope text not null check(scope in ('class','global')),status text not null default 'pending' check(status in ('pending','published','rejected')),created_at timestamptz default now());
alter table public.custom_lessons enable row level security;revoke all on public.custom_lessons from anon,authenticated;grant select on public.custom_lessons to authenticated;
create policy custom_lesson_read on public.custom_lessons for select to authenticated using(owner=auth.uid() or public.my_role()='admin' or (status='published' and (scope='global' or public.in_class(class_id))));
create function public.create_lesson(p_title text,p_body text,p_video text,p_scope text,p_class uuid default null) returns uuid language plpgsql security definer set search_path='' as $$declare lid uuid;begin if public.my_role() not in ('teacher','admin') then raise exception 'Ruxsat yo‘q';end if;if p_scope not in ('class','global') then raise exception 'Nashr turi noto‘g‘ri';end if;if p_scope='class' and (p_class is null or not public.owns_class(p_class)) then raise exception 'Guruhga ruxsat yo‘q';end if;insert into public.custom_lessons(owner,class_id,title,body,video_url,scope,status) values(auth.uid(),case when p_scope='class' then p_class else null end,trim(p_title),p_body,nullif(p_video,''),p_scope,case when p_scope='class' or public.my_role()='admin' then 'published' else 'pending' end) returning id into lid;return lid;end$$;
create function public.review_lesson(p_id uuid,p_approve boolean) returns void language plpgsql security definer set search_path='' as $$declare uid uuid;begin if public.my_role()<>'admin' then raise exception 'Ruxsat yo‘q';end if;update public.custom_lessons set status=case when p_approve then 'published' else 'rejected' end where id=p_id and scope='global' and status='pending' returning owner into uid;if uid is null then raise exception 'Dars topilmadi';end if;insert into public.notifications(user_id,body) values(uid,case when p_approve then 'Darsingiz tasdiqlandi.' else 'Darsingiz rad etildi.' end);end$$;
create table ilmora_private.document_shares(token uuid primary key default gen_random_uuid(),document_id uuid not null unique references public.documents on delete cascade,created_at timestamptz default now());
create function public.share_document(p_id uuid) returns uuid language plpgsql security definer set search_path='' as $$declare t uuid;begin if auth.uid() is null or not exists(select 1 from public.documents where id=p_id and owner=auth.uid()) then raise exception 'Ruxsat yo‘q';end if;insert into ilmora_private.document_shares(document_id) values(p_id) on conflict(document_id) do update set document_id=excluded.document_id returning token into t;return t;end$$;
create function public.revoke_document_share(p_id uuid) returns void language plpgsql security definer set search_path='' as $$begin if auth.uid() is null or not exists(select 1 from public.documents where id=p_id and owner=auth.uid()) then raise exception 'Ruxsat yo‘q';end if;delete from ilmora_private.document_shares where document_id=p_id;end$$;
create function public.read_shared_document(p_token uuid) returns jsonb language plpgsql security definer set search_path='' as $$declare d jsonb;begin if auth.uid() is null then raise exception 'Avval tizimga kiring';end if;select jsonb_build_object('title',doc.title,'body',doc.body) into d from ilmora_private.document_shares s join public.documents doc on doc.id=s.document_id where s.token=p_token;if d is null then raise exception 'Havola bekor qilingan yoki mavjud emas';end if;return d;end$$;
revoke execute on function public.create_lesson(text,text,text,text,uuid),public.review_lesson(uuid,boolean),public.share_document(uuid),public.revoke_document_share(uuid),public.read_shared_document(uuid) from public,anon,authenticated;
grant execute on function public.create_lesson(text,text,text,text,uuid),public.review_lesson(uuid,boolean),public.share_document(uuid),public.revoke_document_share(uuid),public.read_shared_document(uuid) to authenticated;
commit;
